package net.officefloor.hq.app.quickadd;

import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonAliasRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Finds the person on the sheet going by the name or an alias, ignoring case; when there is none, adds them with grade A and records
 * it as the person form would (the person, then how the figures moved), noting the figures afterwards so the
 * claim's own rollup counts only what the claim moved.
 */
public class FindOrAddPerson {
    public void find(@Val QuickAddName name, @Val Sheet sheet, @Val Rollup before, PersonRepository people, PersonAliasRepository aliases,
            SheetRepository sheets, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit, Out<Person> personOut,
            Out<Rollup> rollupOut) {
        Optional<Person> found = PersonAliasRepository.findByNameOrAlias(
                people.findBySheetIdOrderByIdAsc(sheet.getId()), aliases, sheet.getId(), name.name());
        if (found.isPresent()) {
            personOut.set(found.get());
            return;
        }
        Person added = new Person(sheet.getId(), name.name(), "A");
        added.setAddedOn(sheet.getToday());
        Person person = people.saveAndFlush(added);
        String by = AuditUser.decode(user);
        audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + by + " name=" + person.getName()
                + " grade=" + person.getGrade());
        Rollup now = Rollup.of(sheet.getId(), sheets, people, claims, rates, grades);
        now.changesSince(before, sheet.getId(), by).forEach(audit::record);
        personOut.set(person);
        rollupOut.set(now);
    }
}
package net.officefloor.hq.app.paste;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRules;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonAliasRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Finds each line's person on the sheet by name or alias, ignoring case, and makes its DRAFT claim by the claim form's rules —
 * all of them before any is stored, so a refused line adds nothing; a line repeating a reference of an earlier
 * line, ignoring case, is refused too. Then adds the claims in order, each recorded
 * and logged as the claim form records and logs it.
 */
public class AddPastedClaims {
    public void add(@Val PastedLines pasted, @Val Sheet sheet, PersonRepository people, PersonAliasRepository aliases, ClaimRepository claims,
            PeriodRepository periods, PersonGradeRepository grades, RateRepository rates, ClaimLogRepository log,
            HolidayRepository holidays,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit,
            Out<PastedClaims> addedOut) throws InvalidClaimException {
        List<Person> onSheet = people.findBySheetIdOrderByIdAsc(sheet.getId());
        List<Person> persons = new ArrayList<>();
        List<Claim> made = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int at = 0;
        for (PastedLine line : pasted.lines()) {
            at++;
            Person person = PersonAliasRepository.findByNameOrAlias(onSheet, aliases, sheet.getId(), line.name())
                    .orElse(null);
            if (person == null) {
                throw new InvalidClaimException("Line " + at + ": " + line.name() + " is not on the sheet.");
            }
            try {
                made.add(ClaimRules.make(line.claim(), sheet, person, claims, periods, grades, holidays));
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + at + ": " + e.getMessage());
            }
            if (line.claim().ref() != null && !refs.add(line.claim().ref().toLowerCase(Locale.ROOT))) {
                throw new InvalidClaimException("Line " + at + ": the reference " + line.claim().ref()
                        + " is already used in this paste.");
            }
            persons.add(person);
        }
        String by = AuditUser.decode(user);
        for (int i = 0; i < made.size(); i++) {
            Claim claim = claims.saveAndFlush(made.get(i));
            ClaimRules.auditAdded(claim, persons.get(i).getName(), by, audit);
            ClaimRules.log(claim, sheet, log, people, rates, grades, by);
        }
        addedOut.set(new PastedClaims(made.size()));
    }
}

